import sailpoint.object.Identity;
import sailpoint.object.Filter;

// Get the group object from the args map
Object groupObj = args.get("group");

// Safely extract department value via reflection
String department = null;
if (groupObj != null) {
    try {
        department = groupObj.getClass().getMethod("getValue", (Class[]) null).invoke(groupObj, (Object[]) null);
    } catch (Exception e) {
        log.error("Could not get group value from group object: " + e);
    }
}

if (department == null || department.isEmpty()) {
    return null;
}

// Create filter to find manager in the department
Filter filter = Filter.and(
  Filter.eq("department", department),
  Filter.like("title", "%Manager%")
);

// Search for matching identities
List results = context.getObjects(Identity.class, filter);

if (results != null && results.size() > 0) {
    return results.get(0);  // Assign first matching manager
}

return null;  // No match, leave group owner blank
